const VOICE_DATA = {"file":"voice/ep11.mp3","lines":{"ep11_001":{"who":"TAKUTO","text":"Previously. Sieg held the old stone bridge against Morvudd, and counted to sixteen.","mono":true,"off":0.25,"dur":5.291,"env":"011778536799332134222000002327763123469982255556765312441067665554421578863123312544220035556642344321000000000453023576541142013232235201210131110000000000000"},"ep11_002":{"who":"TAKUTO","text":"Mr. Sable stepped between two seconds and told me. He opened the crossing. He took Haruki first, as bait.","mono":true,"off":5.9407,"dur":7.296,"env":"003696441046553233247676246523311775000032110444442031344322246410243323333121256655311222111000000045215784014444330114676632222100000000000000005213970212487755553010333211005776321122011023322111454311000000000000000"},"ep11_003":{"who":"TAKUTO","text":"Haruki put his hand on my shoulder. The door stayed shut. We killed a Calamity.","mono":true,"off":13.6367,"dur":5.099,"env":"001599966773011344301263543311354444434334333333215543311211100000042147677643430154332033327862000000000000024101116865324112334444543221110000000000000"},"ep11_004":{"who":"TAKUTO","text":"And under the cathedral, forty people sleep in crystal with their Brands scraped out.","mono":true,"off":19.1353,"dur":4.885,"env":"002567765673550146200054442123221100000000004999565101344103433332134420333310116644300322221222004432124544444333333003443200045642100000000000000"},"ep11_005":{"who":"SABLE","text":"Three hundred years in the ice, Tyr. Sealed by the same people who sealed the red one.","mono":false,"off":24.4207,"dur":5.547,"env":"00001369752366643332123453332331223332234433113332002312323211100000000001366577973125753235864433452121321012210122355432322113213453110132222100000000000000000000000"},"ep11_006":{"who":"SABLE","text":"Wake up. There is a city of gold to the south. And the Saint would like to keep it.","mono":false,"off":30.3673,"dur":4.864,"env":"00013889831257742011101233322466543444333200235433221111111245334333221000000000001234435655554211122232100110001321011110000000000000000000000000"},"ep11_007":{"who":"CROWD","text":"Praise the Saint! The Order saved the plains!","mono":false,"off":35.6313,"dur":2.773,"env":"006988897410663333686432100000014424799445431223455542103201156542211111110000000000"},"ep11_008":{"who":"CROWD2","text":"Morvudd is dead! The Saint's light killed it!","mono":false,"off":38.8047,"dur":2.347,"env":"02579985377466321126777652110332222655432214775410112444223320000000000"},"ep11_009":{"who":"LUCIEN","text":"People of Lumen. The Calamity Morvudd is slain. The golden wall held, as it always will.","mono":false,"off":41.5513,"dur":5.355,"env":"12863016575225887565422220000000433498797666644545666674146521123433225665543211100000000053379776425655447765542223765433211024335621036765254423202565421100000"},"ep11_010":{"who":"LUCIEN","text":"The Rite continues. Every light you lend keeps the wall bright.","mono":false,"off":47.306,"dur":3.691,"env":"059659877410013664144866664432223200000000279526865576653012465567655442011453023106633566554211576543210011000"},"ep11_011":{"who":"RIN","text":"The Order saved the plains. The Order never left the walls.","mono":false,"off":51.3967,"dur":3.093,"env":"044158994774433466761004301056554433332210000442378957776666146545631000442454432211112100000"},"ep11_012":{"who":"WICK","text":"He said the Saint's light killed Morvudd. Takuto killed Morvudd. With Haruki. And Sieg. And a wolf.","mono":false,"off":54.89,"dur":5.461,"env":"03644683254436665241367653000112866633576555423332110000000001796115842277641112766425765665234332112341114987667620115544334334335544311113454433465321000000000000"},"ep11_013":{"who":"NEMU","text":"Nobody ever cheers for the wolf.","mono":false,"off":60.7513,"dur":2.304,"env":"0068983376524210000000017913730354237754311024310151443234420001100000"},"ep11_014":{"who":"HARUKI","text":"He is asking them to lend more light. After the bridge. After everything. He is asking for more.","mono":false,"off":63.4553,"dur":4.907,"env":"0399964247775511777765633476677666576777655687642000003785114867641788864333200057621473279437651043222000000000798642378755305763137686654321100000"},"ep11_015":{"who":"TAKUTO","text":"Why more?","mono":false,"off":68.762,"dur":0.853,"env":"00269988778988643110000000"},"ep11_016":{"who":"HARUKI","text":"I do not know. But I am going to ask him. Tonight. To his face.","mono":false,"off":70.0153,"dur":3.136,"env":"17985988874368776654366677776764787666373577554214533221022888878751000117765420476422233320000"},"ep11_017":{"who":"NEMU","text":"It is cold.","mono":false,"off":73.5513,"dur":0.981,"env":"059827643302115665321111020000"},"ep11_018":{"who":"RIN","text":"It is midsummer, Nemu.","mono":false,"off":74.9327,"dur":1.429,"env":"0485696327997124266556545555555543311000000"},"ep11_019":{"who":"NEMU","text":"I know. It is still cold.","mono":false,"off":76.762,"dur":1.792,"env":"014998678976420000000766553414576410321276432000002000"},"ep11_020":{"who":"SIEG","text":"Rin stitched me so tight I cannot laugh. It is a form of torture.","mono":false,"off":78.954,"dur":4.245,"env":"18986655543201852241087764327665112265555302566311886665553004676654331100000000000007899767751005766566653102187642242533221000"},"ep11_021":{"who":"GIDEON","text":"I built him a crutch. Brass. With a spring in the foot.","mono":false,"off":83.5993,"dur":3.413,"env":"0156424996412445410111664210011000000000002798753211111000000000453543331003687433444433100126421000000"},"ep11_022":{"who":"SIEG","text":"It bounces, Gideon. I bounce down the corridor like a frog.","mono":false,"off":87.4127,"dur":3.733,"env":"2974177666675436876643100059768876554310000000005996686556543028666662026867764776666556562075111587654322110000"},"ep11_023":{"who":"GIDEON","text":"Efficiently. You bounce efficiently.","mono":false,"off":91.546,"dur":2.325,"env":"0331113973223431112110000000000463298765432111221001642111221012110000"},"ep11_024":{"who":"VALENTINE","text":"Takuto. Tofu did something naughty at the speech today. He appraised the Saint. From across the plaza.","mono":false,"off":94.2713,"dur":5.419,"env":"0149611155303155543321012568400352540325420234555566653333101222023201320231343322210000000000484001556653200223325433210100000000145411156413103100255443212111000"},"ep11_025":{"who":"TAKUTO","text":"And?","mono":false,"off":100.09,"dur":0.555,"env":"01689876534100000"},"ep11_026":{"who":"VALENTINE","text":"Sanctum, rank S. As expected.","mono":false,"off":101.0447,"dur":2.389,"env":"001299874102565655556651236764211111015632530222104530001333110000000000"},"ep11_027":{"who":"VALENTINE","text":"And a second signature, folded inside the first. It reads as static.","mono":false,"off":103.834,"dur":4.053,"env":"03677443369301564133523541033233221000699876375155552323554411300046653210120100000000002741357666213343223126544222000000"},"ep11_028":{"who":"SIEG","text":"Sable.","mono":false,"off":108.2873,"dur":0.811,"env":"0133987777886656554210000"},"ep11_029":{"who":"VALENTINE","text":"Not Sable himself. A key. Lucien carries a Rift key, bound into his Brand. The same kind Gideon dug out of his forge floor.","mono":false,"off":109.498,"dur":7.296,"env":"068860255378861664555344256432000000033011155532100000000000499956635653113555643453267400020104333300497666555243331243200055443322321000000000004455478788862136666641016925555640578513554202433002555411410035543221100"},"ep11_030":{"who":"GIDEON","text":"Then the Saint can open Rifts. Sideways. Anywhere he likes.","mono":false,"off":117.194,"dur":3.819,"env":"0388876333577521144410268610134444665210000110000000000013399875420232111110000000016968643544421343344321100111000"},"ep11_031":{"who":"TAKUTO","text":"The forge. The crossing. Grey Hollow.","mono":false,"off":121.4127,"dur":2.368,"env":"023111398898863143004111598753434432100000377776542456653222100000000000"},"ep11_032":{"who":"VALENTINE","text":"Perhaps. Or perhaps Sable opens them, and Lucien only pays the rent. Either way, darling, we are guests in the house of a liar.","mono":false,"off":124.1807,"dur":7.019,"env":"0332249862003330056301432257402444456740464205784002443230033232024554765454354214666552011344433203313443210120000000000000015792797366665420366665433333310035544200167421231023034433113442222113333433321111000"},"ep11_033":{"who":"TAKUTO","text":"Haruki is going to talk to him. Tonight.","mono":false,"off":131.5993,"dur":2.688,"env":"001799978883011344565431265445203389510034433322111000000001356566542110000000000"},"ep11_034":{"who":"SIEG","text":"...Then go with him. And stand where Lucien can see you.","mono":false,"off":134.6873,"dur":3.221,"env":"1799777643977665677411886554200000000399542197766554557776677776443576631787543348765444432110000"},"ep11_035":{"who":"HARUKI","text":"Mira from Osaka. She taught me how to buy bread. You told me she went home.","mono":false,"off":138.3087,"dur":3.947,"env":"02899877787213874106776543666640216654322332534696225676666646446566323777642210000385238654675442655653335764211100000"},"ep11_036":{"who":"LUCIEN","text":"...You went under the cathedral.","mono":false,"off":142.6553,"dur":1.728,"env":"0225788459775120377646742630237511116665234432211000"},"ep11_037":{"who":"HARUKI","text":"Forty beds of crystal, Lucien. Forty people with nothing left inside them. Tell me what the Rite really does.","mono":false,"off":144.7833,"dur":5.867,"env":"00179895775437776445630013595530276543457775333543320000017887664013864036546613777620565565775201567543357766531311000000000000319976777577402655877620367764564246542111332100"},"ep11_038":{"who":"LUCIEN","text":"It keeps this city alive.","mono":false,"off":151.05,"dur":1.707,"env":"2972022975112205753322269736656656787665423321000000"},"ep11_039":{"who":"LUCIEN","text":"Saint Lumen sits on a scar in the sky. The oldest one. A Rift that never closes. My Sanctum is the only thing holding it shut.","mono":false,"off":153.1567,"dur":7.616,"env":"0124964147986665444222475113554533311666655554433331166544322210000000000165258866355321144433210000047755995200004630367743630215766652222211210000000000166643225865410253423330363137776655410265542137655345443201222276321000000"},"ep11_040":{"who":"LUCIEN","text":"And a Sanctum that size burns Brands the way a lamp burns oil. Every consecration buys the city a year.","mono":false,"off":161.1727,"dur":6.528,"env":"0387843339865510264556530133286455553210058666543342100676555542116447665555456766521000077665553202577642210000000000000006973486112477523330228654332445422754444542201433227724433332246542211000"},"ep11_041":{"who":"HARUKI","text":"So there is no road home.","mono":false,"off":168.1007,"dur":1.749,"env":"02548975988886649888777655479877745567654222111000000"},"ep11_042":{"who":"LUCIEN","text":"There is no road home. There never was. Skyfallen have the brightest Brands in the world, Haruki. You are the oil.","mono":false,"off":170.25,"dur":6.293,"env":"079888552997787437877742226653332100058778885266436654321133200000000014438976411378655544367312620386665243420006875555444365533676654421113765568620221543210000003887763164114677532110000"},"ep11_043":{"who":"HARUKI","text":"...And me?","mono":false,"off":176.9433,"dur":0.917,"env":"0596898877777765554443200000"},"ep11_044":{"who":"LUCIEN","text":"You were to be the last. Frozen Hour, burning for a hundred years. No more children in crystal after you.","mono":false,"off":178.2607,"dur":6.101,"env":"0389576145347624745566543211320000000000001298776436654125666545433110687665554431015655211376542552123665532211320000000005897766666510434765314645454101275331144433553002432332210000"},"ep11_045":{"who":"HARUKI","text":"You were going to put me in a bed and call it a gift.","mono":false,"off":184.762,"dur":2.432,"env":"0399797449877674431282367766753577776431146522177756555422775311110330000"},"ep11_046":{"who":"LUCIEN","text":"I was going to save a hundred thousand people with you. Do you think I wanted to? I caught you myself.","mono":false,"off":187.594,"dur":5.461,"env":"03796742299766623333338666265225866537731004765553255301365202442341003433210000000000025788405763266664566642421235754310000000156402379720255554433325864221000000"},"ep11_047":{"who":"TAKUTO","text":"You caught him after Sable pushed him.","mono":false,"off":193.4553,"dur":2.133,"env":"0132022599854444332003430013222234443133200024322101210000000000"},"ep11_048":{"who":"LUCIEN","text":"...Ruinbreaker. You walk very quietly for someone so loud.","mono":false,"off":195.9887,"dur":3.563,"env":"01246999876635765201454310000003865986201139665630011065555541023311233434754444432333755444565543221210000"},"ep11_049":{"who":"TAKUTO","text":"Haruki. We are leaving.","mono":false,"off":199.9513,"dur":1.621,"env":"0017997687400223443210123455333434312210000000000"},"ep11_050":{"who":"LUCIEN","text":"Leave, then. Both of you. Go and see how long a city lasts without its wall. You will not have to wait long.","mono":false,"off":201.9727,"dur":5.909,"env":"0459987722187655530598742115411233210000000000289866653334554346666558665553333284455456765422312205266533204103566755322000000000387587778766532256201564277641014666544321100000"},"ep11_051":{"who":"HARUKI","text":"Takuto. The windows. They are icing over.","mono":false,"off":208.282,"dur":2.304,"env":"1299721295237765546656777757655444310667752466654336656654213221200000"},"ep11_052":{"who":"HARUKI","text":"I helped him, Takuto. For two years. I went to the Guild halls and told Skyfallen about the Rite. I told them it was a road home.","mono":false,"off":210.986,"dur":6.805,"env":"0799853998500339666333588751139843287654213640528877676532114320000000000008997886235485469765454776665446753176534431577675105766667637652155588764100000000000018983439755777632565675578876444453211100000"},"ep11_053":{"who":"HARUKI","text":"I told Mira it would be fine. She was scared of the chair, and I held her hand, and I told her it would be fine.","mono":false,"off":218.1913,"dur":5.568,"env":"089952479776469887777863342664576211786664321100000000000001449788654148788574473253587666642477776642587634776558776654421157777740517765437875136437521187553221100000"},"ep11_054":{"who":"TAKUTO","text":"You did not know.","mono":false,"off":224.1593,"dur":1.109,"env":"0136549925999961367765332100000000"},"ep11_055":{"who":"HARUKI","text":"I did not ask. That is worse. I am the one who stops things. I never stopped to ask.","mono":false,"off":225.6687,"dur":4.203,"env":"0697785697675766665440026865764445775312322000000578877675666787533028665123103776554430037877753664321776301453554211331000000"},"ep11_056":{"who":"TAKUTO","text":"...You remember the high schoolers? At the vending machine?","mono":false,"off":230.2713,"dur":3.072,"env":"002355596678646944732257554442015553332111221000000075015324876644434442433133210000000000000"},"ep11_057":{"who":"HARUKI","text":"You were breaking their noses.","mono":false,"off":233.7433,"dur":1.749,"env":"05987964279776223766657776667777666433432223222100000"},"ep11_058":{"who":"TAKUTO","text":"You did not ask me why. You just put your hand on my shoulder. You trusted I would stop.","mono":false,"off":235.8927,"dur":5.269,"env":"003638636878877777644104554447666532111100000000035348640019611574346666665555454443433267755213211000000034213219854410453333443233124420676521000000000000000"},"ep11_059":{"who":"TAKUTO","text":"Trusting people is not the bad thing, Haruki. He is the bad thing.","mono":false,"off":241.562,"dur":4.288,"env":"011994521655212354104553233335555104215555452001045443322115554444320110221010000000000003557743115215555552001033210000000000000"},"ep11_060":{"who":"HARUKI","text":"...When did you learn to say things like that?","mono":false,"off":246.25,"dur":2.112,"env":"0478987857556886587765654327766510576666438763103876543101000000"},"ep11_061":{"who":"TAKUTO","text":"I have been walking for a long time. With a lot of people who talk too much.","mono":false,"off":248.762,"dur":4.267,"env":"00035779421675544799501244311134443345554444223344432110000000000000334646788582002244103433331031454100241433322100023210000000"},"ep11_062":{"who":"HARUKI","text":"Ha. The cat. The thread. The fire. The old man who counts.","mono":false,"off":253.4287,"dur":2.795,"env":"007987572229875104751127997744464116977765433212774477756766666775212864321124331000"},"ep11_063":{"who":"TAKUTO","text":"And now you.","mono":false,"off":256.6233,"dur":0.939,"env":"16777799999843355422110000000"},"ep11_064":{"who":"CROWD","text":"Snow! In midsummer! It is snowing!","mono":false,"off":257.962,"dur":2.304,"env":"0111579999752345556652022432211100013223212222135445432110100000000000"},"ep11_065":{"who":"CROWD2","text":"The Saint has raised the wall! Look at the sky!","mono":false,"off":260.666,"dur":2.581,"env":"029532289887478432367667632055337877765421001386045123222189776542210000000000"},"ep11_066":{"who":"RIN","text":"Something is walking out of the snow.","mono":false,"off":263.6473,"dur":1.835,"env":"02298740187877733334897201455555521333331554332111000000"},"ep11_067":{"who":"WICK","text":"That is not a giant. That is a MOUNTAIN with an AXE.","mono":false,"off":265.882,"dur":2.987,"env":"079849954789989742399877654311100006995965898878776234665554066313677763024443421100000000"},"ep11_068":{"who":"CROWD","text":"The wall is cracking! The Saint's wall is cracking!","mono":false,"off":269.2687,"dur":3.093,"env":"035434789999654433100115654300111100000023444465653220235555543222220001344320011110000000000"},"ep11_069":{"who":"CROWD2","text":"Run! Everybody run!","mono":false,"off":272.762,"dur":1.664,"env":"02799777566410278416741666544423554432221000000000"},"ep11_070":{"who":"HARUKI","text":"Tyr. The Frost Titan. It is in the oldest stories. A rune axe that breaks wards.","mono":false,"off":274.826,"dur":4.352,"env":"13598887547411899753102288762045532003868765877775105776546643311777764432233200576679887765777413205621077632312566654322111320000"},"ep11_071":{"who":"TAKUTO","text":"Sable sent it.","mono":false,"off":279.578,"dur":1.131,"env":"0013999538742226986513432100000000"},"ep11_072":{"who":"HARUKI","text":"To crack the Sanctum. So Lucien needs more Brands to mend it. All of them.","mono":false,"off":281.1087,"dur":4.075,"env":"028523499883010565433877651026433320001338766887633666666766443677776425886666553026776777664432000000488886553214221100000"},"ep11_073":{"who":"RIN","text":"Talk later. Fight now.","mono":false,"off":285.5833,"dur":1.387,"env":"025994015778846641114665402444332222100000"},"ep11_074":{"who":"RIN","text":"You still have Kaito's scarf on your wrist.","mono":false,"off":287.37,"dur":2.155,"env":"03523029986435661001255665566522220365554300144444423542111110000"},"ep11_075":{"who":"TAKUTO","text":"I said I would give it back with me attached.","mono":false,"off":289.9247,"dur":2.197,"env":"024433259984545544211643421355543001310343331021344210001210000000"},"ep11_076":{"who":"RIN","text":"...If it goes red today. If you have to open the door.","mono":false,"off":292.522,"dur":2.731,"env":"0571371039997443499962033427665443200025124754674103550477302566631564443211000000"},"ep11_077":{"who":"TAKUTO","text":"I will not.","mono":false,"off":295.6527,"dur":0.917,"env":"1477537976677765311002100000"},"ep11_078":{"who":"RIN","text":"You might. Listen. If you do, I am going to stand in front of you. Like you stood in front of Gideon. Like Nemu stood.","mono":false,"off":296.97,"dur":6.037,"env":"02689999762000046963443655431003721267426999877402767777762798752334316566646541117655412333210002774012533412893665211665531027625443332100135530025555555544323322443220100000000000"},"ep11_079":{"who":"TAKUTO","text":"Rin, no.","mono":false,"off":303.4073,"dur":0.875,"env":"014899776779998532100000000"},"ep11_080":{"who":"RIN","text":"You do not get to decide what I risk. I told you that at Marrowmere. I meant it.","mono":false,"off":304.682,"dur":4.373,"env":"046448999876200473022324444456666661266566642585312332000000000006852268724755864156104665666665555443320144566655422132100100000000"},"ep11_081":{"who":"RIN","text":"And I would rather stand in front of you than behind anyone else. That is all. Do not make a thing of it.","mono":false,"off":309.4553,"dur":5.632,"env":"0785888975852498782674553277777846563211877651246554146645522236666664565655555566532113432100000000000386438654988786543200000278787773156511420046554431232002000000000"},"ep11_082":{"who":"TAKUTO","text":"...I will not make a thing of it.","mono":false,"off":315.4873,"dur":1.643,"env":"00058986777899834662154111166655553123100000000000"},"ep11_083":{"who":"RIN","text":"You are making a face.","mono":false,"off":317.53,"dur":1.259,"env":"04799989884116766310176543211222100000"},"ep11_084":{"who":"TAKUTO","text":"I do not have a face.","mono":false,"off":319.1887,"dur":1.301,"env":"0268549689997888354110885311133210000000"},"ep11_085":{"who":"RIN","text":"Wick says everybody has a face.","mono":false,"off":320.89,"dur":1.813,"env":"0497011226774230566237624555344323422410044322101110000"},"ep11_086":{"who":"GIDEON","text":"Flame boy. Gloves off. These are Takoyaki Mark Two. Steel weave, and a coil of furnace brass. They hold heat even in the cold.","mono":false,"off":323.1033,"dur":8.832,"env":"0015899766652277764211000000000357622235653210000000000000000000488546730124662014665666311123443332000021454221000000000001231027777755433555332210000244301137865344110000577533222100034542210111000000000000254236875411001023210010013441144444443100114764211100000"},"ep11_087":{"who":"WICK","text":"Mark Two! Gideon! I love Mark Two! What do they do?","mono":false,"off":332.3353,"dur":2.773,"env":"058971005367675312865666653116654578621567774000432755433531254265431332211100000000"},"ep11_088":{"who":"GIDEON","text":"They keep your fire alive when the world is trying to freeze it. Do not look at my hat.","mono":false,"off":335.5087,"dur":5.205,"env":"0158302224311242111115776543333344456543211110000000000578864346888743313331024554311111114643231100000000000000000005867987641012531241233332211234210000000"},"ep11_089":{"who":"WICK","text":"I am not looking at your hat. I am looking at the hat-shaped area near your hat.","mono":false,"off":341.114,"dur":4.032,"env":"0467877787989942389214668613653466431032000000077778777799214777306422487314537765002146665565565655444422364310021000000"},"ep11_090":{"who":"SIEG","text":"Valentine. Give me my swords.","mono":false,"off":345.546,"dur":2.219,"env":"0488665666642596666666662000000596588766655663322677664432223220000"},"ep11_091":{"who":"VALENTINE","text":"You have four broken ribs and a frog crutch, darling. You will bounce into battle.","mono":false,"off":348.1647,"dur":4.288,"env":"046445821000577872047764011455435555310242333211135555520011242014410465454322222200000000001555940586665314424323104432211111000"},"ep11_092":{"who":"SIEG","text":"Then I will bounce. Give me my swords.","mono":false,"off":352.8527,"dur":2.496,"env":"059764345655566653166555665422220000000049768876665566322267765443322221000"},"ep11_093":{"who":"VALENTINE","text":"...One sword. And you stay at the infirmary door. With the children. Promise.","mono":false,"off":355.7487,"dur":3.947,"env":"03489785443555555412146544233145545300334453000476665433302433222100001420330452554312322200000000138764322101221000000"},"ep11_094":{"who":"SIEG","text":"I promise to stay at the infirmary door.","mono":false,"off":360.0953,"dur":2.88,"env":"078730397656666411386443038776666630000000584019887776310286666766666543776543221100000"},"ep11_095":{"who":"VALENTINE","text":"That is not the whole promise.","mono":false,"off":363.3753,"dur":1.92,"env":"0598612574589999960045214887651011576665433212321000000000"},"ep11_096":{"who":"SIEG","text":"It is the part I can keep. The boy taught me that one.","mono":false,"off":365.6953,"dur":3.371,"env":"089754666531663028766663235774118775122776532000000000001997696566664042875205777467653004654332210000"},"ep11_097":{"who":"TAKUTO","text":"Everyone together. Now.","mono":false,"off":369.466,"dur":1.493,"env":"057524765664442199823322100014566431110000000"},"ep11_098":{"who":"RIN","text":"Red Thread! Its ankles!","mono":false,"off":371.3593,"dur":1.387,"env":"059973002699897366124666675114443222210000"},"ep11_099":{"who":"RIN","text":"The threads are freezing! They are snapping in the cold!","mono":false,"off":373.146,"dur":2.645,"env":"03300138987225751111566643354332100057864433356664004455554302145543322100000000"},"ep11_100":{"who":"WICK","text":"My fire! My fire is going out!","mono":false,"off":376.1913,"dur":1.771,"env":"067721199777777677664106876666543167555543321102100000"},"ep11_101":{"who":"HARUKI","text":"Frozen Hour!","mono":false,"off":378.362,"dur":1.237,"env":"01117986767558665566666554433333100000"},"ep11_102":{"who":"HARUKI","text":"Nothing. It did nothing. You cannot stop something that is already ice.","mono":false,"off":379.9993,"dur":3.605,"env":"0489874038766315535756777620542222000000387238977777313321877731332765412666574654456765755555565321123221000"},"ep11_103":{"who":"VALENTINE","text":"Encore! Dance for me, big one!","mono":false,"off":384.0047,"dur":2.027,"env":"0799885213666541037766216410445443300785011443322320000000000"},"ep11_104":{"who":"VALENTINE","text":"It is walking straight through my stage!","mono":false,"off":386.4313,"dur":2.283,"env":"045635642224793002443122201355542000023334332121143322210011000000000"},"ep11_105":{"who":"GIDEON","text":"Cogwheel Core! Every gate in the north wall, close!","mono":false,"off":389.114,"dur":3.264,"env":"01379973114443101145321000000000000027932375210376431011235454456642110135443211000011365310111000"},"ep11_106":{"who":"GIDEON","text":"Valentine, the axe!","mono":false,"off":392.778,"dur":1.643,"env":"01399896776512356432111000000002555443210001211000"},"ep11_107":{"who":"TAKUTO","text":"Get behind me!","mono":false,"off":394.8207,"dur":1.109,"env":"0049710096223676655433211100000000"},"ep11_108":{"who":"TAKUTO","text":"One!","mono":false,"off":396.33,"dur":0.619,"env":"0136998654320000000"},"ep11_109":{"who":"TAKUTO","text":"Two!","mono":false,"off":397.3487,"dur":0.597,"env":"133999975432100000"},"ep11_110":{"who":"VALENTINE","text":"Takuto. You spent both on us.","mono":false,"off":398.346,"dur":2.176,"env":"015993012651133555543223422203543110067763003333222211111000000000"},"ep11_111":{"who":"TAKUTO","text":"Gideon said I would waste the second one on somebody old.","mono":false,"off":400.922,"dur":3.371,"env":"015956678763332999824027663452226565331003332285003322232210024441232555434434322356632100000000000000"},"ep11_112":{"who":"VALENTINE","text":"I am NOT old.","mono":false,"off":404.6927,"dur":1.451,"env":"16677788899888997405058776533320211000000000"},"ep11_113":{"who":"WICK","text":"Takoyaki Mark Two! Burn only the cold! BURN THE COLD!","mono":false,"off":406.5433,"dur":2.987,"env":"038931598986015778998400074598765431598877766655402177655422101776766302165432210210000000"},"ep11_114":{"who":"WICK","text":"It is working! My fire is back!","mono":false,"off":409.93,"dur":1.771,"env":"056896544898301765556655211887666555330065321000000000"},"ep11_115":{"who":"RIN","text":"Warm threads! Wick, keep them warm! Red Thread!","mono":false,"off":412.1007,"dur":2.539,"env":"02599989612389888415412785011023630047776567776655443367751012254322111000000"},"ep11_116":{"who":"NEMU","text":"Wick, duck!","mono":false,"off":415.0393,"dur":0.875,"env":"001798102103664321001000000"},"ep11_117":{"who":"GIDEON","text":"Every bolt in the plaza! Cogwheel Core! Bury its feet!","mono":false,"off":416.314,"dur":3.883,"env":"027832477420399963220123455310125664323221000000000000278997313675410114764211000000000006786443332013311134320001000"},"ep11_118":{"who":"TAKUTO","text":"Break!","mono":false,"off":420.5967,"dur":0.64,"env":"00489976520011100000"},"ep11_119":{"who":"VESPER","text":"White Gale!","mono":false,"off":421.6367,"dur":1.131,"env":"0035979852100297787665444332100000"},"ep11_120":{"who":"VESPER","text":"The wind is freezing in the air!","mono":false,"off":423.1673,"dur":2.069,"env":"078533998888872335322100015666532355532455553116554332222210000"},"ep11_121":{"who":"NEMU","text":"The infirmary. Takuto, the axe is going to come down on the infirmary.","mono":false,"off":425.6367,"dur":5.547,"env":"01117763111799764321100000000000000000000000000000032486002174052243221000000000000014400498520013332365027677762510212666645776655432210686555455531114576532211100000"},"ep11_122":{"who":"NEMU","text":"Sieg is in there. And the children from the plains.","mono":false,"off":431.5833,"dur":3.563,"env":"00112388766302200753256653333221110000000000000000000000598660344347664214543211345430220445542110000222000"},"ep11_123":{"who":"TAKUTO","text":"Rin. It is talking.","mono":false,"off":435.546,"dur":1.344,"env":"01367766531165553302148962012211000000000"},"ep11_124":{"who":"RIN","text":"Then tell it no.","mono":false,"off":437.29,"dur":1.067,"env":"04999975437879614666543321000000"},"ep11_125":{"who":"TAKUTO","text":"Not this time.","mono":false,"off":438.7567,"dur":1.109,"env":"0135788201994412366553221100000000"},"ep11_126":{"who":"CROWD2","text":"Mister Sieg, is the big ice man coming in here?","mono":false,"off":440.266,"dur":2.645,"env":"04983127533235556631121255211722047743659985321245565321433334322233332100000000"},"ep11_127":{"who":"CROWD","text":"Hush. Let him listen.","mono":false,"off":443.3113,"dur":1.621,"env":"0014898521110123554344444454322111101100000000000"},"ep11_128":{"who":"SIEG","text":"Nobody is coming through this door. Not the ice man. Not anybody. I promised a very scary lady.","mono":false,"off":445.3327,"dur":6.613,"env":"0897775465546654355410258666565212287665466432006765543310000000049762066203566644307866655555200000068764100277777646544424443100000000000016861159655565410167658655566443400577666655655542332210000"},"ep11_129":{"who":"CROWD2","text":"How many of us are there?","mono":false,"off":452.346,"dur":1.643,"env":"01259885444555565552155322244312433332210000000000"},"ep11_130":{"who":"SIEG","text":"Let me count. One, two, three... twenty-two. Twenty-two of you. Good. I will remember every one.","mono":false,"off":454.3887,"dur":5.803,"env":"0772387312996667532320000006977762446976652224887776664100000000238987368524398766641000349773664339877556766652000001998764332000000068878877767766656751037744665444322110000"},"ep11_131":{"who":"CROWD2","text":"Why do you count?","mono":false,"off":460.5913,"dur":1.301,"env":"0136988784544552114555543212211110000000"},"ep11_132":{"who":"SIEG","text":"Because it is a thing I do. And because tomorrow morning, I am going to count you again, and get the same number.","mono":false,"off":462.2927,"dur":6.592,"env":"065139654465456544651110046555531034555531364432210000000000000486752186530237655445555555655545554444100000000056655444435555333012664331236543256554333200000000576466200254322665555555443322111000"},"ep11_133":{"who":"AKURO","text":"Finally. You knocked. Do you know how long I have waited for you to knock?","mono":true,"off":469.2847,"dur":4.651,"env":"00124876665455654564421001246465587666532100002320000023345557996434456777542255777665444245455312235454445311123343422342343333321000000000"},"ep11_134":{"who":"TAKUTO","text":"Ten minutes. Kill the Titan. Save the city. Then you give me back.","mono":false,"off":474.3353,"dur":3.733,"env":"0248776678777630230114988336122488642012211100123487672114343348723211100014555544114741344324776210000000000000"},"ep11_135":{"who":"AKURO","text":"Ten minutes. And if I want eleven?","mono":true,"off":478.4687,"dur":2.176,"env":"033687889987878641233211366794247865436888433545567742343221100000"},"ep11_136":{"who":"TAKUTO","text":"Then my friends will come and get me.","mono":false,"off":481.0447,"dur":1.984,"env":"000878998722279875526620222787654212454269950122110000000000"},"ep11_137":{"who":"AKURO","text":"Ha! Your friends. The cat. The thread. The fire. The boy who stops time. They will try.","mono":true,"off":483.4287,"dur":6.315,"env":"0012368677644567851113797766676542213421111356665420001463101223587885532110000014421147766676664454322114633137877979986444344424655553113331222455554333322135533234321222475443322211110000"},"ep11_138":{"who":"TAKUTO","text":"They always try.","mono":false,"off":490.1433,"dur":1.195,"env":"004677899567645302177664221110000000"},"ep11_139":{"who":"AKURO","text":"...Deal, boy. Open the door. All the way.","mono":true,"off":491.738,"dur":2.581,"env":"012234777986433799977540135883256775634867775454200255665533544555432211100000"},"ep11_140":{"who":"AKURO","text":"Three hundred years.","mono":true,"off":494.7193,"dur":1.344,"env":"00124799767787645762235666664322112221000"},"ep11_141":{"who":"AKURO","text":"Three hundred years in a headsman's axe, in a graveyard nobody visits.","mono":true,"off":496.4633,"dur":5.461,"env":"00014467765434688633795322325657878655432224466422235774323247767764221378774310012321000013577652112336876677624789989743466566788425765433332125653233221001222100"},"ep11_142":{"who":"AKURO","text":"Hello, world.","mono":true,"off":502.3247,"dur":1.152,"env":"01369766698777433576656432111111000"},"ep11_143":{"who":"RIN","text":"His hair. His eyes. Takuto?","mono":false,"off":503.8767,"dur":1.856,"env":"03944116888875379438866666623202477401571325543221000000"},"ep11_144":{"who":"AKURO","text":"Not at home, thread girl. Leave a message.","mono":true,"off":506.1327,"dur":2.688,"env":"026898986642335888775641114699642236887654310001358855455888677534444441112322000"},"ep11_145":{"who":"AKURO","text":"Tyr! Old friend! Do you remember me?","mono":true,"off":509.2207,"dur":2.24,"env":"01554645777623889796222238998765321223455558788978556645532221000000"},"ep11_146":{"who":"AKURO","text":"I remember YOU. You were always slow.","mono":true,"off":511.8607,"dur":2.347,"env":"01787655786469886456653344432101246677358876565544443225665432110000000"},"ep11_147":{"who":"AKURO","text":"Rune axe. Breaks wards. Cute. I break rune axes.","mono":true,"off":514.6073,"dur":3.712,"env":"0135965765435666431112101456642222335667855442211100111456553100000145532775211346665542245532112222322111111000"},"ep11_148":{"who":"WICK","text":"He broke its axe. He broke the axe that breaks things.","mono":false,"off":518.7193,"dur":2.624,"env":"0653599861393238876541122100574288851026666664212146321665312210443211121100000"},"ep11_149":{"who":"AKURO","text":"Ruinbreaker! Ha ha ha ha!","mono":true,"off":521.7433,"dur":1.963,"env":"01369657775436666312565211245542256532145432123432110000000"},"ep11_150":{"who":"HARUKI","text":"It is gone. Tyr is gone. Takuto, you did it. Takuto?","mono":false,"off":524.106,"dur":3.179,"env":"059888653267667655332377675541386666544321785215752276665575347844420000001885212763335332110000"},"ep11_151":{"who":"AKURO","text":"Now. The Saint.","mono":true,"off":527.6847,"dur":1.131,"env":"0168999999885565434778653321110000"},"ep11_152":{"who":"AKURO","text":"I have nine minutes left. I would like to spend them on gold.","mono":true,"off":529.2153,"dur":4.267,"env":"02577753335798535898887876799977889866512343247786531100001100000036785677447985411345554325987787664446765521368977332221011000"},"ep11_153":{"who":"SIEG","text":"Takuto. I can see you in there. Count with me. One. Two.","mono":false,"off":533.882,"dur":3.904,"env":"0197631297633386665552000377218874332755566555666555555420000239655431006751166554420000000006876555403349754332100000"},"ep11_154":{"who":"AKURO","text":"The Laughing Blade, on a frog crutch. Oh, this is the best day of my life.","mono":true,"off":538.186,"dur":5.931,"env":"0135986777765541125666433234578646466544324665311113576566863220011268752101233210000000003589879544422476744331376532366310246754333210025566655432134454344333444333211000000000"},"ep11_155":{"who":"SIEG","text":"Three. Four. You are not him, Takuto. You never were.","mono":false,"off":544.5167,"dur":3.371,"env":"024897666411177666655300000028987777555433685555430034865104975235865555300005988866457644444322110000"},"ep11_156":{"who":"AKURO","text":"He is busy, old man. He cannot hear you over all the gold.","mono":true,"off":548.2873,"dur":4.629,"env":"0013544565432102699664445666420136686642367765543322110000000242123687556888531111246666544565642477425753257776554223421247655322211011000"},"ep11_157":{"who":"VESPER","text":"...There it is.","mono":false,"off":553.3167,"dur":1.173,"env":"001457988778732279976443211121100000"},"ep11_158":{"who":"LUCIEN","text":"Vesper of the Guild. By the authority of the Saint. Execute the Calamity.","mono":false,"off":554.89,"dur":4.245,"env":"02597431006675215421477654433110000057653666420017777766435455211433332665533210100000000574133341116630141226556665554222210000"},"ep11_159":{"who":"LUCIEN","text":"Now.","mono":false,"off":559.5353,"dur":0.747,"env":"03899877766666422100000"},"ep11_160":{"who":"VESPER","text":"I always come, error. I told you.","mono":false,"off":560.682,"dur":2.091,"env":"169614999769874302188877630366555432036630516766522244333200000"},"ep11_161":{"who":"RIN","text":"Vesper, no! He is still in there!","mono":false,"off":563.1727,"dur":1.771,"env":"039733203877887776531256333315765555554344321110000000"},"ep11_162":{"who":"VESPER","text":"White Gale. Final Verse.","mono":false,"off":565.3433,"dur":1.899,"env":"034888941000497877654430000696666666532265432212222211000"},"ep11_163":{"who":"AKURO","text":"Oh, you are lovely. Again. Do it again.","mono":true,"off":567.642,"dur":2.581,"env":"014897976433588996444787831124543100234325898653210002479797553356543311100000"},"ep11_164":{"who":"HARUKI","text":"Frozen Hour! Takuto, come back!","mono":false,"off":570.6233,"dur":2.176,"env":"001179777658764566666665413686411773357665422376655654322000000000"},"ep11_165":{"who":"AKURO","text":"One second. That is all your friendship buys, little clock.","mono":true,"off":573.1993,"dur":3.797,"env":"014688887987444468863127664311011469777567443236789875886411378866655576311478755534342224564311113576542100000000"},"ep11_166":{"who":"RIN","text":"Red Thread! Wrist to wrist!","mono":false,"off":577.3967,"dur":1.493,"env":"059973001469988634467533036546753212220100000"},"ep11_167":{"who":"RIN","text":"It burned. It burned the thread.","mono":false,"off":579.29,"dur":1.536,"env":"05101999988885315510288777655112265433212000000"},"ep11_168":{"who":"RIN","text":"Takuto. I cannot hold you.","mono":false,"off":581.226,"dur":1.792,"env":"017871129815289998751565024777664111576641234322100000"},"ep11_169":{"who":"NEMU","text":"Takuto.","mono":false,"off":583.418,"dur":0.96,"env":"00327994021896061665432100000"},"ep11_170":{"who":"NEMU","text":"It is me. I am shouting. Can you hear me?","mono":false,"off":584.778,"dur":2.475,"env":"017258545247775200000000798754344427654322100000000021678851126564321000000"},"ep11_171":{"who":"AKURO","text":"The cat. Move, cat. I have an appointment with a Saint.","mono":true,"off":587.6527,"dur":3.328,"env":"0129411356677531124577997621113566554210002576765567556886300013678743443333424434434645423210111000"},"ep11_172":{"who":"NEMU","text":"No. You can go through me. That is all right. I know how. I have done it seven times.","mono":false,"off":591.3807,"dur":6.293,"env":"004899875310151227645874212247754321100000000000000002675466576555215443210020000037975776631234332111000000000000000000000000000000000003986821048997653002333367405553411244432100001433100"},"ep11_173":{"who":"NEMU","text":"Takuto. If you are in there. Watch.","mono":false,"off":598.074,"dur":2.432,"env":"0133860218535276643100007221776777898864533211100000000004775321000354200"},"ep11_174":{"who":"AKURO","text":"...Ha.","mono":true,"off":600.906,"dur":0.811,"env":"0156533589987764432100000"},"ep11_175":{"who":"TAKUTO","text":"NEMU!","mono":false,"off":602.1167,"dur":0.725,"env":"0135799877654220000000"},"ep11_176":{"who":"TAKUTO","text":"Get out. GET OUT. Give me back.","mono":false,"off":603.242,"dur":1.728,"env":"0276778773111696866531000014435543165431100000000000"},"ep11_177":{"who":"AKURO","text":"...Fine. Fine, boy. Six minutes early. You have terrible manners.","mono":true,"off":605.37,"dur":4.523,"env":"0011379867766766521115978767788653589999965532234449722334778865222147887633211000002465468631012113575768644555455455554432221112221100"},"ep11_178":{"who":"TAKUTO","text":"Nemu. Nemu. Wake up. You always wake up.","mono":false,"off":610.2927,"dur":2.816,"env":"0245677666665544555555554332244202688410000000000244599963555561254301454100000000000"},"ep11_179":{"who":"WICK","text":"How long does it take? Rin, how long does it take?","mono":false,"off":613.5087,"dur":2.475,"env":"017997579987758554134587630000025877665324876556666654443203244310000000000"},"ep11_180":{"who":"RIN","text":"I do not know. I have never seen it.","mono":false,"off":616.3833,"dur":1.92,"env":"0474488998614888877653036666237775154444445554321011000000"},"ep11_181":{"who":"TAKUTO","text":"Ten seconds. She said ten seconds, then the blanket. Then she wakes up hungry.","mono":false,"off":618.7033,"dur":4.715,"env":"0136655523228962013322111122132225652101135444322166400232211133333213455444101321000000000000004554333434755112465001124433212210000000000000"},"ep11_182":{"who":"TAKUTO","text":"...Eleven. Twelve.","mono":false,"off":623.818,"dur":1.152,"env":"03556898256542042069764211000000000"},"ep11_183":{"who":"HARUKI","text":"Takuto...","mono":false,"off":625.37,"dur":1.045,"env":"01239877521487643477655432210000"},"ep11_184":{"who":"TAKUTO","text":"Thirteen. Fourteen. Fifteen.","mono":false,"off":626.8153,"dur":1.92,"env":"0018985125555411278730434433210000019721002433210100000000"},"ep11_185":{"who":"NEMU","text":"...","mono":false,"off":629.1353,"dur":0.265,"env":"00226922"},"ep11_186":{"who":"NEMU","text":"Takuto. I am so hungry.","mono":false,"off":629.8007,"dur":2.069,"env":"022651025513436432100000000001699764633447653115666422211000000"},"ep11_187":{"who":"TAKUTO","text":"...You idiot. You stupid, lazy, idiot cat.","mono":false,"off":632.27,"dur":2.603,"env":"0024552279465565300000023344116640154123355554323321332333300113553100000000000"},"ep11_188":{"who":"NEMU","text":"You heard me.","mono":false,"off":635.2727,"dur":0.896,"env":"001972225999601453422000000"},"ep11_189":{"who":"TAKUTO","text":"I heard you.","mono":false,"off":636.5687,"dur":0.875,"env":"255531379983132432111000000"},"ep11_190":{"who":"NEMU","text":"Then it was worth it. One left. I will be very careful with the last one. Promise.","mono":false,"off":637.8433,"dur":6.229,"env":"0139774116541046652101310002000000000000000005898765545543210001021000000000000000037965614861276555520221255511113221032024323444441332301111100000000000000000000000113765533211023232000"},"ep11_191":{"who":"WICK","text":"She is alive! She is ALIVE! Somebody get her food! All the food!","mono":false,"off":644.4727,"dur":3.136,"env":"02379659767987877412326764685688876443113348759485218726621006665522045633510045422111000000000"},"ep11_192":{"who":"RIN","text":"...Don't ever do that again, Nemu. Ever.","mono":false,"off":648.0087,"dur":2.176,"env":"003995138725833577368642521766566666777766554310056412432100000000"},"ep11_193":{"who":"NEMU","text":"I only have one more. So, probably only once more.","mono":false,"off":650.5847,"dur":4.16,"env":"01120188666522245110045444443221111000000000000000000000233457542100000000000215561251234310039987665430234203411432211110000"},"ep11_194":{"who":"GIDEON","text":"The cat! Is the cat all right? Somebody tell me the cat is all right!","mono":false,"off":655.1447,"dur":4.267,"env":"02410325675420000000002332140011245521113543333432110000000000000001369887353132111466443312201113432000022123343333233311100000"},"ep11_195":{"who":"NEMU","text":"I am all right. I am hungry. Do you have food in your hat?","mono":false,"off":659.8113,"dur":4.139,"env":"02257766776664145443210004100000000000004898764123888621211000000000000000000002215842472221119988355544422443210003000000000"},"ep11_196":{"who":"GIDEON","text":"...I have a sandwich in my hat. Emergency sandwich. Take it.","mono":false,"off":664.35,"dur":3.989,"env":"025645772332222356554322320113344332112432100000000000000036889999412254212232111115555432111100000000000135641112100000"},"ep11_197":{"who":"VALENTINE","text":"Tofu, read her. Gently.","mono":false,"off":668.7393,"dur":1.92,"env":"1159993111675422565562213443221001447985202332221000000000"},"ep11_198":{"who":"VALENTINE","text":"Nine Lives. Lives remaining, one of nine. Oh, darling.","mono":false,"off":671.0593,"dur":3.285,"env":"078989998778766645513661466788526428677777654333243420166544322221000000005999762057655543222121000"},"ep11_199":{"who":"NEMU","text":"One is enough. Most people only get one.","mono":false,"off":674.7447,"dur":3.072,"env":"001597886544555543110111000000000000000000599944402031561034420399766630456420100121211000000"},"ep11_200":{"who":"VESPER","text":"...The order says execute the Calamity.","mono":false,"off":678.2167,"dur":2.304,"env":"0024963489984884323776421000882022252114640141226667666643233222210000"},"ep11_201":{"who":"RIN","text":"Vesper.","mono":false,"off":680.9207,"dur":0.704,"env":"0499733301886544210000"},"ep11_202":{"who":"VESPER","text":"I am looking at the boy in the snow, holding a cat. I do not see a Calamity.","mono":false,"off":682.0247,"dur":4.267,"env":"05799878986960138963005206767755445543333327866544421126642555520112365431002210000004672688886651022325540115555544442222121000"},"ep11_203":{"who":"VESPER","text":"Tell the Saint the wind took his letter.","mono":false,"off":686.6913,"dur":2.325,"env":"0216987535622212778642010004653266655554200223401143214554333222210000"},"ep11_204":{"who":"VESPER","text":"One more time, error, and I will not be able to tear it. Do not make me write the next one.","mono":false,"off":689.4167,"dur":5.099,"env":"027989999877650241465544444301344433322100036543567525667776563003555512302210321255443320032100000000148888777203665100365326652004455410231114432222000"},"ep11_205":{"who":"TAKUTO","text":"I will not.","mono":false,"off":694.9153,"dur":0.917,"env":"1477537976677765311002100000"},"ep11_206":{"who":"VESPER","text":"You said it. You finally said it. Damn you.","mono":false,"off":696.2327,"dur":2.432,"env":"0059733229973873000036410097788876555422216641441000067655555443332321000"},"ep11_207":{"who":"LUCIEN","text":"People of Lumen. The Titan is dead. But the wall is broken across half the sky.","mono":false,"off":699.0647,"dur":4.757,"env":"11984027777326799867644433100000551334876410255544330048776542110000000007406754588888765643100787621364520248643322465310023442167654322211000"},"ep11_208":{"who":"LUCIEN","text":"Stay in your homes. Stay close to the light. Your Saint will mend it.","mono":false,"off":704.222,"dur":3.541,"env":"01305977666676435876654444322220576620317865310252655576653201000000000028743337865301454556666652321000000"},"ep11_209":{"who":"CROWD","text":"Who killed the Titan? Was it the Order?","mono":false,"off":708.1633,"dur":2.688,"env":"006751011169998753235103124876412221111100001454345400034312455653122111000000000"},"ep11_210":{"who":"CROWD2","text":"It was a red thing. A red demon. I saw it from the roof.","mono":false,"off":711.2513,"dur":3.2,"env":"069668448634898420004544443214642268752203334333322220000000168633369984013334323444320111000000"},"ep11_211":{"who":"TAKUTO","text":"That is your sixth bowl.","mono":false,"off":714.8513,"dur":1.429,"env":"0158978853465342265012101267875421110000000"},"ep11_212":{"who":"NEMU","text":"Dying is very hungry work. The eighth time is the hungriest. Ask anyone.","mono":false,"off":716.6807,"dur":6.187,"env":"003555665544333223310055444443011156653133320332210001000000000000000000000000130069520011031265554443210005542034113566412221100022230200000000000000000024653122202002976543121100000000"},"ep11_213":{"who":"TAKUTO","text":"...What did it feel like? This time.","mono":false,"off":723.2673,"dur":1.92,"env":"0258438577111367985456544100001365540226554321111000000000"},"ep11_214":{"who":"NEMU","text":"Not cold. That was the strange part. Every other time was cold first.","mono":false,"off":725.5873,"dur":5.867,"env":"00454300002116664321000010000000000000000000016653100000045420334332124776665443002123211000100000000000000000039811664138526503124444443343333011145443222011002332110022220100"},"ep11_215":{"who":"NEMU","text":"This time you were holding me. Even before you came back. Some part of you was already holding me.","mono":false,"off":731.854,"dur":6.891,"env":"037333304237777654200000065454211654523432222110000000000000000000000028997139874353211046654420312445441443221000100000000000000000000000123379775032487454012432100000365300587636615411145443243211211100000"},"ep11_216":{"who":"TAKUTO","text":"I hit you, Nemu.","mono":false,"off":739.1447,"dur":1.237,"env":"26642169402424444444454443211000000000"},"ep11_217":{"who":"NEMU","text":"Akuro hit me. You caught me. I know the difference. I have a lot of experience.","mono":false,"off":740.782,"dur":6.251,"env":"06984003279767765520118500034432100000000000000004612324653000343210000000000000000000000037986899983192467411102210003333100000000000000001685358226444566746315124340356443332221002333100"},"ep11_218":{"who":"TAKUTO","text":"One left.","mono":false,"off":747.4327,"dur":0.875,"env":"013788676799964211011000000"},"ep11_219":{"who":"NEMU","text":"One left. So now I am like everybody else. It is a little bit exciting.","mono":false,"off":748.7073,"dur":5.696,"env":"001597766665420001012000000000000000013379898777776410189866555556402002991147504534423322332100133331000000000000000000000002744654542276465106533102323143443221111000000"},"ep11_220":{"who":"TAKUTO","text":"...Do not use it. Please. Not for me.","mono":false,"off":754.8033,"dur":2.325,"env":"0015879995224674457510000114976444433212456786101135444321100000000000"},"ep11_221":{"who":"NEMU","text":"I will try very hard. Pass me the seventh bowl.","mono":false,"off":757.5287,"dur":3.541,"env":"02394561362288999611787666622255432100020000000000000000000232899444532999513663337961785020067753210000000"},"ep11_222":{"who":"LUCIEN","text":"Knights of the Order. Ring the city. Every gate, every bridge. Nobody leaves Saint Lumen.","mono":false,"off":761.47,"dur":5.269,"env":"058987411436225655677862542110000000049967754533336772543210000068524752126765421100268313652103777654111221000000059887348645544655531333664212577554222100000"},"ep11_223":{"who":"HUNTER","text":"Saint? The people will ask why.","mono":false,"off":767.1393,"dur":2.453,"env":"00113988776311541137640155435545455542110012454433322221000000000000000000"},"ep11_224":{"who":"LUCIEN","text":"Tell them the wall is broken, and their Saint is going to mend it. Tell them to stay close to the light.","mono":false,"off":769.9927,"dur":5.483,"env":"126976536656547633577666553443200067775101332221000004786774333275554124330275441244566666523310000000000000012797643655412333304755202158653220242454456543211001000"},"ep11_225":{"who":"HUNTER","text":"Yes, Saint.","mono":false,"off":775.8753,"dur":1.088,"env":"001357999962100000554433210000000"},"ep11_226":{"who":"RIN","text":"You told me. Before you did it. You said, it is talking. Then you said, not this time.","mono":false,"off":777.3633,"dur":4.544,"env":"03650327997428877640262115886674158825530010000000474443998862365574330211697301154444326666653332666511555540004423222444332222000000000"},"ep11_227":{"who":"TAKUTO","text":"I made a deal with it. Ten minutes.","mono":false,"off":782.3073,"dur":1.941,"env":"02555665652145699754420343100000225655445442211002321000000"},"ep11_228":{"who":"RIN","text":"And it kept four of them for itself.","mono":false,"off":784.6487,"dur":1.877,"env":"058971024781012106888973266652136774024446543210100000000"},"ep11_229":{"who":"TAKUTO","text":"I know.","mono":false,"off":786.926,"dur":0.747,"env":"03677778999854210000000"},"ep11_230":{"who":"RIN","text":"My thread burned, Takuto. My brother's thread. It has never burned. Not even in the Rift where he died.","mono":false,"off":788.0727,"dur":5.803,"env":"0367861122989331039988777766321022675111564041466655444556620587527644530126654421000000000554856599872484119866544432100035776577347787676337741101054334314443222211100000000"},"ep11_231":{"who":"TAKUTO","text":"...Then I need to be stronger than a thread.","mono":false,"off":794.2753,"dur":2.069,"env":"000378899999741432545740199997646743555411113898431000000000000"},"ep11_232":{"who":"RIN","text":"No. You need to stop making deals with something that lies.","mono":false,"off":796.7447,"dur":3.136,"env":"05899989752003789972243440598762004777501367632676755431251234541145545521355543222111221000000"},"ep11_233":{"who":"TAKUTO","text":"You are right.","mono":false,"off":800.2807,"dur":0.896,"env":"014769974499876321012100000"},"ep11_234":{"who":"RIN","text":"Say it again. I want to remember it.","mono":false,"off":801.5767,"dur":1.941,"env":"02458999957138877653100568546752323566666653344320022000000"},"ep11_235":{"who":"TAKUTO","text":"You are right, Rin.","mono":false,"off":803.918,"dur":1.109,"env":"0015599538998640023654321100000000"},"ep11_236":{"who":"TAKUTO","text":"I let it out. I promised myself I never would, and I let it out.","mono":false,"off":805.4273,"dur":4.075,"env":"000467559987759887531000000000002561021888777561154554445655210235555553244323576542111024444443344434244431100000000000000"},"ep11_237":{"who":"HARUKI","text":"You saved the city. And then you came back. Both of those are true.","mono":false,"off":809.902,"dur":3.371,"env":"059985433877753246543288655433310047887777741228666655988742010007877520654378766435531222575322100000"},"ep11_238":{"who":"RIN","text":"And next time I will have a thicker thread.","mono":false,"off":813.6727,"dur":2.091,"env":"058999611350337778777532576774456255001721265201147433201000000"},"ep11_239":{"who":"TAKUTO","text":"There cannot be a next time.","mono":false,"off":816.1633,"dur":1.621,"env":"0058830249979995125766664035223765532110100000000"},"ep11_240":{"who":"HARUKI","text":"There will be. Tomorrow. Lucien's Sanctum is cracked across half the sky. Tyr did what Sable sent it to do.","mono":false,"off":818.1847,"dur":5.696,"env":"039987854477663137877667777532222100000269977434666432486540455554201277762014113865431276530034331576553322200000000133888747644674123325766535543226655311254245431100000"},"ep11_241":{"who":"HARUKI","text":"To mend it, he needs Brands. Not forty. Every Brand in the city. He will raise the Great Sanctum over all of Lumen and harvest them at once.","mono":false,"off":824.2807,"dur":7.552,"env":"03798787667477311167677644300477666542333200037775100006678633212100000027953676422776666545565543333773321100000000000000068777547866554155315876411333276652145666524524666553246665554432135421678633544104655201456421013221000"},"ep11_242":{"who":"RIN","text":"Every Hunter. Every child with a mark. Us.","mono":false,"off":832.2327,"dur":2.496,"env":"058326873258895225665300489326750352666777225456666555431010025532123321000"},"ep11_243":{"who":"HARUKI","text":"And the Rift under the city stays shut for a thousand years. That is the trade he will make. I know him. He will make it.","mono":false,"off":835.1287,"dur":5.973,"env":"069988656995102765654543455654311666555543322397200016663006876665446655565422123200000000005994366524633267676467645566676531000000000001778878777666753323215756666665311321000000"},"ep11_244":{"who":"TAKUTO","text":"Then we break it.","mono":false,"off":841.502,"dur":1.024,"env":"0046666631389876111432100000000"},"ep11_245":{"who":"HARUKI","text":"Nothing has ever broken a Sanctum, Takuto.","mono":false,"off":842.926,"dur":2.688,"env":"058998402667886435863875448876216665543357766301464544302488631168523464322110000"},"ep11_246":{"who":"TAKUTO","text":"I cracked one.","mono":false,"off":846.014,"dur":1.003,"env":"1464012998740113664222110000000"},"ep11_247":{"who":"HARUKI","text":"...You did.","mono":false,"off":847.4167,"dur":0.981,"env":"037899988756988876434543100000"},"ep11_248":{"who":"LUCIEN","text":"The wall is broken across half the sky. I need every Brand in the city to mend it.","mono":false,"off":848.798,"dur":4.971,"env":"019855798887765324430008876114555202486433123664200023434116754433221000000000000277889884313772366521277766555435354333327734331224556666541221010000"},"ep11_249":{"who":"SABLE","text":"The Great Sanctum. Over everything. It will drink them all, you know. Hunters, children, your little clock.","mono":false,"off":854.1687,"dur":6.187,"env":"000152165874137997454310022222210002321322443122210122221000000001222522454330014543343321234343233221000000000137664342223234531564343212332222222221011124443210000000000000000000000000"},"ep11_250":{"who":"LUCIEN","text":"Then they will be safe. Forever. In the light.","mono":false,"off":860.7553,"dur":2.389,"env":"018998886863575444367665321000000119889972565420048876756687653210120000"},"ep11_251":{"who":"SABLE","text":"Oh, Lucien. That is the most beautiful lie you have ever told. I am so proud of you.","mono":false,"off":863.5447,"dur":5.504,"env":"0001799975466653554222221000014541135632234334300012343332112333344433233222221331121122122222121100000000000112333467764322101133322111001111100000000000000000000000"},"ep11_252":{"who":"TAKUTO","text":"Next time: the Great Sanctum rises over the whole city.","mono":false,"off":869.4487,"dur":3.477,"env":"036850340279987542110000421399964013336765420035444433456766622343225442232520155542232255312100000000000"},"ep11_253":{"who":"TAKUTO","text":"Haruki gives me three seconds. That is all I need.","mono":false,"off":873.326,"dur":3.371,"env":"001699877885102145421275221444201034433432763002211012100000000467464343466654444444443210000000000000"},"ep11_254":{"who":"TAKUTO","text":"And a Rift to Earth flickers open in front of me.","mono":false,"off":877.0967,"dur":2.688,"env":"013565349961104461025675211111541013433320035772015444331114544321211000000000000"},"ep11_255":{"who":"TAKUTO","text":"Final episode. Ruinbreaker.","mono":false,"off":880.1847,"dur":2.133,"env":"0007988878773068304455466543310000237989766457652012321000000000"}}};
